const match = String(msg.topic || "").match(/^station\/([1-3])\/data$/);
if (!match) return null;

const id = Number(match[1]);
const input = msg.payload;
if (!input || typeof input !== "object" || Array.isArray(input)) return null;

let stations = context.get("stations");
if (!stations) {
    stations = {};
    for (let i = 1; i <= 3; i++) {
        stations[i] = {
            id: i, status: "UNKNOWN", connectionStatus: "UNKNOWN",
            power: 0, energy: 0,
            temperature: null, soc: null, batteryCapacityKWh: null,
            fullIn: "--", faultCode: "", errorCode: null, errorMessage: null,
            powerHistory: [], temperatureHistory: []
        };
    }
}

const s = stations[id];
const now = Date.now();
const wasOffline = s.connectionStatus === "OFFLINE";
const events = [];

const allowedStatus = ["AVAILABLE", "FREE", "CHARGING", "FAULT"];
const incomingStatus = String(input.status || s.status || "UNKNOWN").toUpperCase();
if (allowedStatus.includes(incomingStatus)) {
    s.status = incomingStatus === "FREE" ? "AVAILABLE" : incomingStatus;
}

if (input.power !== undefined && Number.isFinite(Number(input.power))) {
    s.power = Math.max(0, Number(input.power)) / 1000;
}
if (input.energy !== undefined && Number.isFinite(Number(input.energy))) {
    s.energy = Math.max(0, Number(input.energy)) / 1000;
}
if (input.temperature !== undefined && input.temperature !== null && Number.isFinite(Number(input.temperature))) {
    s.temperature = Number(input.temperature);
}
if (input.soc !== undefined && input.soc !== null && Number.isFinite(Number(input.soc))) {
    s.soc = Math.min(100, Math.max(0, Number(input.soc)));
}
if (input.batteryCapacityKWh !== undefined && Number.isFinite(Number(input.batteryCapacityKWh))) {
    s.batteryCapacityKWh = Math.max(0, Number(input.batteryCapacityKWh));
}

const fc = String(input.faultCode || input.errorCode || "").toUpperCase();
if (fc) {
    s.faultCode = fc;
    s.errorCode = fc;
    if (fc === "E1") s.errorMessage = "QUÁ NHIỆT";
    else if (fc === "E2") s.errorMessage = "MẤT KẾT NỐI";
    else if (fc === "E3") s.errorMessage = "DỪNG KHẨN CẤP";
}

s.connectionStatus = "ONLINE";
s.lastSeen = now;

if (wasOffline) {
    events.push({
        stationNo: id,
        event_type: "CONNECTION",
        event_code: "ONLINE",
        title: "Trạm online lại",
        message: "Nhận lại telemetry MQTT",
        event_id: "online-" + id + "-" + now
    });
}

if (s.status === "FAULT" && s.errorCode && ["E1", "E3"].includes(s.errorCode)) {
    events.push({
        stationNo: id,
        event_type: "FAULT",
        event_code: s.errorCode,
        title: s.errorCode === "E1" ? "Quá nhiệt" : "Dừng khẩn cấp",
        message: s.errorMessage || s.errorCode,
        event_id: "fault-" + id + "-" + s.errorCode + "-" + Math.floor(now / 60000)
    });
}

s.powerHistory.push({ time: now, value: s.power });
if (s.temperature !== null) {
    s.temperatureHistory.push({ time: now, value: s.temperature });
}
s.powerHistory = s.powerHistory.slice(-30);
s.temperatureHistory = s.temperatureHistory.slice(-30);

s.fullIn = "--";
if (s.status === "CHARGING" && s.soc !== null && s.batteryCapacityKWh > 0 && s.power > 0 && s.soc < 100) {
    const remainingKWh = s.batteryCapacityKWh * (100 - s.soc) / 100;
    const minutes = Math.ceil(remainingKWh / s.power * 60);
    if (minutes < 60) {
        s.fullIn = minutes + " phút";
    } else {
        const hours = Math.floor(minutes / 60);
        const mins = minutes % 60;
        s.fullIn = mins ? hours + " giờ " + mins + " phút" : hours + (hours === 1 ? " giờ" : " giờ");
    }
}

stations[id] = s;
context.set("stations", stations);
global.set("evStations", stations);

msg.payload = {
    stations: [stations[1], stations[2], stations[3]],
    updatedAt: now,
    _events: events,
    _stationNo: id
};
return msg;

const p = msg.payload || {};
const id = Number(p.stationId);
const allowed = ["STOP", "EMERGENCY_STOP"];
if (![1, 2, 3].includes(id) || !allowed.includes(String(p.command || ""))) return null;

msg.topic = "station/" + id + "/command";
msg.payload = JSON.stringify({
    stationId: id,
    command: "EMERGENCY_STOP",
    errorCode: "E3",
    commandId: p.commandId || ("cmd-" + id + "-" + Date.now()),
    requestedAt: new Date().toISOString()
});
return msg;

let stations = context.get("stations") || global.get("evStations") || {};
const now = Date.now();
let changed = false;
const events = [];

for (let i = 1; i <= 3; i++) {
  const s = stations[i];
  if (!s || !s.lastSeen) continue;
  const offline = (now - s.lastSeen > 90000);
  if (offline && s.connectionStatus !== "OFFLINE") {
    s.connectionStatus = "OFFLINE";
    if (s.status !== "FAULT" || s.errorCode === "E2") {
      s.status = "FAULT";
      s.faultCode = "E2";
      s.errorCode = "E2";
      s.errorMessage = "DISCONNECTED – no telemetry > 90s";
    }
    s.power = 0;
    changed = true;
    events.push({
      stationNo: i,
      event_type: "CONNECTION",
      event_code: "E2",
      title: "Trạm offline",
      message: "Mất telemetry quá 90 giây",
      event_id: "e2-" + i + "-" + Math.floor(now / 90000)
    });
  }
}
if (!changed) return null;
context.set("stations", stations);
global.set("evStations", stations);
msg.payload = { stations: [stations[1], stations[2], stations[3]], updatedAt: now, _events: events };
return msg;

const events = (msg.payload && msg.payload._events) || [];
if (!events.length) return null;

const map = global.get("evStationMap") || {};
const baseUrl = String(env.get("SUPABASE_URL") || "").replace(/\/+$/, "").replace(/\/rest\/v1$/i, "");
const key = env.get("SUPABASE_SERVICE_ROLE_KEY");
if (!baseUrl || !key) return null;

const rows = [];
const now = new Date().toISOString();
for (const ev of events) {
    const uuid = map[String(ev.stationNo)];
    if (!uuid) continue;
    rows.push({
        station_id: uuid,
        event_type: ev.event_type || "FAULT",
        event_code: ev.event_code || "",
        event_id: ev.event_id || null,
        title: ev.title || "",
        message: ev.message || "",
        payload: ev,
        created_at: now
    });
}
if (!rows.length) return null;

msg.method = "POST";
msg.url = baseUrl + "/rest/v1/station_events";
msg.headers = {
    "apikey": key,
    "Authorization": "Bearer " + key,
    "Content-Type": "application/json",
    "Prefer": "return=minimal,resolution=ignore-duplicates"
};
msg.payload = rows;
msg._loai = "station_events";
return msg;

const _restore = global.get("evSessionsRestore");
if (_restore && typeof _restore === "object") {
    const cur = flow.get("evSessions") || {};
    let merged = false;
    for (const [k, v] of Object.entries(_restore)) {
        if (!cur[k]) { cur[k] = v; merged = true; }
    }
    if (merged) flow.set("evSessions", cur);
    global.set("evSessionsRestore", null);
}

if (!flow.get("tariffConfig")) {
    const shared = global.get("evTariffShared");
    if (shared) flow.set("tariffConfig", shared);
}

const p = msg.payload;
const match = String(msg.topic || "").match(/^station\/([1-3])\/session$/);
if (!match || !p || typeof p !== "object" || Array.isArray(p)) return null;

const stationId = Number(p.stationId || match[1]);
const sessionId = String(p.sessionId || "");
const sequence = Number(p.sequence);
const totalWh = Number(p.totalEnergyWh);
if (![1,2,3].includes(stationId) || !sessionId || !Number.isFinite(sequence) || !Number.isFinite(totalWh) || totalWh < 0) return null;

let timestamp = p.timestamp !== undefined ? new Date(p.timestamp).getTime() : Date.now();
if (!Number.isFinite(timestamp)) return null;

const tariff = flow.get("tariffConfig") || {
    currency: "VND", low: 0, normal: 0, peak: 0,
    lowStart: "00:00", lowEnd: "06:00",
    peakStart: "17:30", peakEnd: "22:30", version: "CHUA_CAU_HINH"
};
const sessions = flow.get("evSessions") || {};
let current = sessions[stationId];

if (!current || current.sessionId !== sessionId) {
    current = {
        stationId: stationId,
        sessionId: sessionId,
        startTime: timestamp,
        lastTime: timestamp,
        lastSequence: sequence,
        lastTotalWh: totalWh,
        energyWh: 0,
        energyByBand: {low: 0, normal: 0, peak: 0},
        costVnd: 0,
        costByBand: {low: 0, normal: 0, peak: 0},
        status: String(p.status || "CHARGING").toUpperCase(),
        tariffVersion: tariff.version,
        tariffVersions: [tariff.version],
        lastPowerW: Math.max(0, Number(p.powerW) || 0)
    };
    sessions[stationId] = current;
    flow.set("evSessions", sessions);
    msg.payload = {
        type: "session_update",
        currentSessions: Object.values(sessions),
        history: flow.get("evSessionHistory") || [],
        tariff: tariff,
        updatedAt: Date.now()
    };
    return msg;
}

if (sequence <= current.lastSequence || timestamp < current.lastTime) return null;

const deltaWh = totalWh - current.lastTotalWh;
const from = current.lastTime;
const to = timestamp;
const durationMs = to - from;
if (deltaWh < -0.001) return null;

function parseMinutes(value, fallback) {
    const parts = String(value || fallback).split(":").map(Number);
    return parts[0] * 60 + parts[1];
}
function getVietnamClock(epochMs) {
    const parts = new Intl.DateTimeFormat("en-GB", {
        timeZone: "Asia/Ho_Chi_Minh",
        weekday: "short", hour: "2-digit", minute: "2-digit", hourCycle: "h23"
    }).formatToParts(new Date(epochMs));
    const values = {};
    parts.forEach(part => { values[part.type] = part.value; });
    const dayMap = {Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6};
    return {minute: Number(values.hour) * 60 + Number(values.minute), day: dayMap[values.weekday]};
}
function inTimeRange(minute, start, end) {
    if (start === end) return false;
    if (start < end) return minute >= start && minute < end;
    return minute >= start || minute < end;
}
function getBand(epochMs) {
    const clock = getVietnamClock(epochMs);
    const lowStart = parseMinutes(tariff.lowStart, "00:00");
    const lowEnd = parseMinutes(tariff.lowEnd, "06:00");
    const peakStart = parseMinutes(tariff.peakStart, "17:30");
    const peakEnd = parseMinutes(tariff.peakEnd, "22:30");
    if (inTimeRange(clock.minute, lowStart, lowEnd)) return "low";
    if (clock.day !== 0 && inTimeRange(clock.minute, peakStart, peakEnd)) return "peak";
    return "normal";
}
const rates = {
    low: Math.max(0, Number(tariff.low) || 0),
    normal: Math.max(0, Number(tariff.normal) || 0),
    peak: Math.max(0, Number(tariff.peak) || 0)
};

if (deltaWh > 0 && durationMs > 0) {
    let cursor = from;
    while (cursor < to) {
        const nextMinute = Math.floor(cursor / 60000) * 60000 + 60000;
        const segmentEnd = Math.min(to, nextMinute);
        const segmentMs = segmentEnd - cursor;
        const segmentWh = deltaWh * (segmentMs / durationMs);
        const band = getBand(cursor + segmentMs / 2);
        current.energyByBand[band] += segmentWh;
        current.costByBand[band] += (segmentWh / 1000) * rates[band];
        cursor = segmentEnd;
    }
    current.energyWh += deltaWh;
    current.costVnd = current.costByBand.low + current.costByBand.normal + current.costByBand.peak;
}

current.lastTime = timestamp;
current.lastSequence = sequence;
current.lastTotalWh = totalWh;
current.lastPowerW = Math.max(0, Number(p.powerW) || 0);
current.status = String(p.status || current.status).toUpperCase();
if (!current.tariffVersions.includes(tariff.version)) current.tariffVersions.push(tariff.version);

const ended = ["COMPLETED", "FINISHED", "STOPPED", "ENDED"].includes(current.status);
if (ended) current.endTime = timestamp;
sessions[stationId] = current;
flow.set("evSessions", sessions);

let history = flow.get("evSessionHistory") || [];
if (ended && !history.some(item => item.sessionId === sessionId && item.stationId === stationId)) {
    history.unshift({
        stationId: stationId,
        sessionId: sessionId,
        startTime: current.startTime,
        endTime: timestamp,
        energyWh: current.energyWh,
        energyByBand: current.energyByBand,
        costVnd: Math.round(current.costVnd),
        costByBand: current.costByBand,
        tariffVersion: current.tariffVersions.join(", ")
    });
    history = history.slice(0, 100);
    flow.set("evSessionHistory", history);
}

msg.payload = {
    type: "session_update",
    currentSessions: Object.values(sessions),
    history: history,
    tariff: tariff,
    updatedAt: Date.now()
};
return msg;

const m = String(msg.topic || "").match(/^station\/([1-3])\/queue$/);
if (!m || !msg.payload || typeof msg.payload !== "object") return null;
const id = Number(msg.payload.stationId || m[1]);
const count = Math.max(0, Number(msg.payload.queueCount ?? msg.payload.waitingVehicles) || 0);
const wait = Math.max(0, Number(msg.payload.estimatedWaitMinutes ?? msg.payload.waitMinutes) || 0);
const entry = {stationId:id, queueCount:count, estimatedWaitMinutes:wait, updatedAt:Date.now()};

let q = flow.get("evQueue") || {};
q[id] = entry;
flow.set("evQueue", q);
global.set("evQueue", q);

msg.payload = {type:"queue_update", queue:Object.values(q)};
return msg;

const m = String(msg.topic || "").match(/^station\/([1-3])\/ota\/status$/);
if (!m) return null;
let p = msg.payload;
if (typeof p === "string") { try { p = JSON.parse(p); } catch(e) { p = {status:p}; } }
p = p || {};
msg.payload = {
  type:"ota_update",
  stationId:Number(p.stationId || m[1]),
  status:String(p.status || p.result || "UNKNOWN"),
  version:String(p.version || p.firmwareVersion || ""),
  message:String(p.message || p.error || ""),
  updatedAt:Date.now()
};
return msg;

const p = msg.payload || {};
const topic = String(msg.topic || "");
if (topic === "admin/ui/command") {
  const id = Number(p.stationId);
  if (![1,2,3].includes(id)) return null;
  const cmd = String(p.command || "");
  if (cmd === "EMERGENCY_STOP") {
    return [{topic:`station/${id}/command`, payload:JSON.stringify({
      stationId:id, command:"EMERGENCY_STOP", errorCode:"E3",
      commandId:`cmd-${id}-${Date.now()}`, requestedAt:new Date().toISOString()
    })}, null, null];
  }
  return null;
}
if (topic === "admin/ui/ota") {
  const id = Number(p.stationId);
  const url = String(p.firmwareUrl || "");
  const knownStations = global.get("evStations") || {};
  const current = knownStations[id];
  if (![1,2,3].includes(id) || !/^https:\/\//i.test(url)) return null;
  if (current && String(current.status).toUpperCase() === "CHARGING") return null;
  return [null, {topic:`station/${id}/ota`, payload:JSON.stringify({
    stationId:id, command:"UPDATE", commandId:`ota-${id}-${Date.now()}`,
    firmwareUrl:url, requestedAt:new Date().toISOString()
  })}, null];
}
if (topic === "admin/ui/tariff") {
  return [null, null, {topic:"admin/tariff/config", payload:p}];
}
return null;

if (msg.topic === "admin/tariff/init") {
    const existing = flow.get("tariffConfig") || global.get("evTariffShared");
    if (existing) {
        flow.set("tariffConfig", existing);
        msg.payload = { type: "tariff_update", tariff: existing };
        return msg;
    }
}

const p = msg.payload || {};
const names = ["low", "normal", "peak"];
const cfg = {};
for (const name of names) {
    const value = Number(p[name]);
    if (!Number.isFinite(value) || value < 0 || value > 100000) return null;
    cfg[name] = value;
}

function validTime(value, fallback) {
    const text = String(value || fallback);
    return /^([01]\d|2[0-3]):[0-5]\d$/.test(text) ? text : fallback;
}

cfg.currency = "VND";
cfg.lowStart = validTime(p.lowStart, "00:00");
cfg.lowEnd = validTime(p.lowEnd, "06:00");
cfg.peakStart = validTime(p.peakStart, "17:30");
cfg.peakEnd = validTime(p.peakEnd, "22:30");
cfg.version = "ADMIN-" + Date.now();
cfg.updatedAt = new Date().toISOString();
cfg.source = "admin";

flow.set("tariffConfig", cfg);
global.set("evTariffShared", cfg);

const map = global.get("evStationMap") || {};
const byStation = global.get("evTariff") || {};
for (const no of ["1", "2", "3"]) {
    byStation[no] = {
        currency: cfg.currency,
        low: cfg.low,
        normal: cfg.normal,
        peak: cfg.peak,
        lowStart: cfg.lowStart,
        lowEnd: cfg.lowEnd,
        peakStart: cfg.peakStart,
        peakEnd: cfg.peakEnd,
        updatedAt: cfg.updatedAt,
        stationId: map[no] || (byStation[no] && byStation[no].stationId) || null
    };
}
global.set("evTariff", byStation);

msg.payload = { type: "tariff_update", tariff: cfg };
return msg;

const tariff = (msg.payload && msg.payload.tariff) ? msg.payload.tariff : null;
if (!tariff || typeof tariff !== "object") {
    node.warn("Không có msg.payload.tariff để ghi Supabase");
    return null;
}

const map = global.get("evStationMap") || {};
const stationNos = ["1", "2", "3"];
const missing = stationNos.filter(n => !map[n]);
if (missing.length) {
    node.warn("Thiếu ánh xạ trạm: " + missing.join(", ") + ". Chạy inject 'Tải cấu hình trạm' trước.");
}

const baseUrl = String(env.get("SUPABASE_URL") || "").replace(/\/+$/, "").replace(/\/rest\/v1$/i, "");
const key = env.get("SUPABASE_SERVICE_ROLE_KEY");
if (!baseUrl || !key) {
    node.error("Thiếu SUPABASE_URL hoặc SUPABASE_SERVICE_ROLE_KEY", msg);
    return null;
}

const now = tariff.updatedAt || new Date().toISOString();
const rows = [];
for (const n of stationNos) {
    const stationId = map[n];
    if (!stationId) continue;
    rows.push({
        station_id: stationId,
        currency: String(tariff.currency || "VND"),
        low_price: Math.max(0, Number(tariff.low) || 0),
        normal_price: Math.max(0, Number(tariff.normal) || 0),
        peak_price: Math.max(0, Number(tariff.peak) || 0),
        low_start: String(tariff.lowStart || "00:00"),
        low_end: String(tariff.lowEnd || "06:00"),
        peak_start: String(tariff.peakStart || "17:30"),
        peak_end: String(tariff.peakEnd || "22:30"),
        updated_at: now
    });
}

if (!rows.length) {
    node.error("Không có station_id nào để ghi station_tariffs", msg);
    return null;
}

msg.method = "POST";
msg.url = baseUrl + "/rest/v1/station_tariffs?on_conflict=station_id";
msg.headers = {
    "apikey": key,
    "Authorization": "Bearer " + key,
    "Content-Type": "application/json",
    "Prefer": "resolution=merge-duplicates,return=representation"
};
msg.payload = rows;
msg._loai = "station_tariffs";
msg._so_ban_ghi = rows.length;
return msg;

const code = Number(msg.statusCode || 0);
const expected = Number(msg._so_ban_ghi || 0);

if (code >= 200 && code < 300) {
    let saved = 0;
    if (Array.isArray(msg.payload)) saved = msg.payload.length;
    else if (msg.payload && typeof msg.payload === "object") saved = 1;
    node.status({ fill: "green", shape: "dot", text: "OK HTTP " + code + " • " + saved + "/" + (expected || saved) + " trạm" });
    msg.payload = { thanh_cong: true, ma_http: code, so_ban_ghi_gui: expected, so_ban_ghi_nhan: saved };
    return msg;
}

node.status({ fill: "red", shape: "ring", text: "Lỗi HTTP " + code });
node.error("Ghi station_tariffs thất bại HTTP " + code, msg);
return null;

const p = msg.payload || {};
if (p.type !== "session_update") return null;

const map = global.get("evStationMap") || {};
const baseUrl = String(env.get("SUPABASE_URL") || "").replace(/\/+$/, "").replace(/\/rest\/v1$/i, "");
const key = env.get("SUPABASE_SERVICE_ROLE_KEY");
if (!baseUrl || !key) return null;

const sessions = p.currentSessions || [];
const rows = [];
const ackList = [];

for (const s of sessions) {
    if (!s || !s.sessionId) continue;
    const uuid = map[String(s.stationId)];
    if (!uuid) continue;

    const statusRaw = String(s.status || "CHARGING").toUpperCase();
    let status = "IN_PROGRESS";
    if (["COMPLETED", "FINISHED", "STOPPED", "ENDED"].includes(statusRaw)) status = "COMPLETED";
    else if (statusRaw === "CANCELLED") status = "CANCELLED";
    else if (["FAILED", "FAULT"].includes(statusRaw)) status = "FAILED";

    const ended = status !== "IN_PROGRESS";
    const energy = Math.max(0, Number(s.energyWh) || 0);
    const cost = Math.round(Math.max(0, Number(s.costVnd) || 0));
    const startIso = s.startTime ? new Date(s.startTime).toISOString() : null;
    const endIso = ended && s.endTime ? new Date(s.endTime).toISOString() : (ended ? new Date().toISOString() : null);
    const duration = startIso ? Math.max(0, Math.floor(((ended && s.endTime ? s.endTime : Date.now()) - new Date(startIso).getTime()) / 1000)) : 0;

    rows.push({
        station_id: uuid,
        session_code: String(s.sessionId),
        status: status,
        started_at: startIso,
        ended_at: endIso,
        energy_consumed_wh: energy,
        duration_seconds: duration,
        total_cost: cost,
        currency: "VND",
        energy_low_wh: Math.max(0, Number(s.energyByBand && s.energyByBand.low) || 0),
        energy_normal_wh: Math.max(0, Number(s.energyByBand && s.energyByBand.normal) || 0),
        energy_peak_wh: Math.max(0, Number(s.energyByBand && s.energyByBand.peak) || 0),
        cost_low: Math.max(0, Number(s.costByBand && s.costByBand.low) || 0),
        cost_normal: Math.max(0, Number(s.costByBand && s.costByBand.normal) || 0),
        cost_peak: Math.max(0, Number(s.costByBand && s.costByBand.peak) || 0),
        tariff_version: String(s.tariffVersion || (s.tariffVersions && s.tariffVersions.join(",")) || ""),
        last_sequence: Number(s.lastSequence) || 0,
        last_total_wh: Number(s.lastTotalWh) || 0,
        updated_at: new Date().toISOString()
    });

    ackList.push({
        stationId: s.stationId,
        sessionId: s.sessionId
    });
}

if (!rows.length) return null;

msg.method = "POST";
msg.url = baseUrl + "/rest/v1/charging_sessions?on_conflict=station_id,session_code";
msg.headers = {
    "apikey": key,
    "Authorization": "Bearer " + key,
    "Content-Type": "application/json",
    "Prefer": "resolution=merge-duplicates,return=minimal"
};
msg.payload = rows;
msg._loai = "charging_sessions";
msg._ackList = ackList;
return msg;

const code = Number(msg.statusCode || 0);
const ackList = msg._ackList || [];

if (code >= 200 && code < 300) {
    node.status({fill:"green", shape:"dot", text:"sessions OK " + code});

    if (ackList.length > 0) {
        const messages = [];
        for (const item of ackList) {
            messages.push({
                topic: "station/" + item.stationId + "/ack",
                payload: JSON.stringify({
                    session_id: item.sessionId,
                    status: "SYNCED"
                }),
                qos: 1
            });
        }
        return [null, messages];
    }
    return null;
}

node.status({fill:"red", shape:"ring", text:"sessions " + code});
node.warn("charging_sessions HTTP " + code + " → Không gửi ACK");
return null;

const url = env.get("SUPABASE_URL");
const key = env.get("SUPABASE_SERVICE_ROLE_KEY");
if (!url || !key) {
    node.error("Thiếu SUPABASE_URL hoặc SUPABASE_SERVICE_ROLE_KEY", msg);
    return null;
}
const baseUrl = url.replace(/\/+$/, "").replace(/\/rest\/v1$/i, "");
msg.method = "GET";
msg.url = baseUrl + "/rest/v1/stations?select=id,station_code,is_active&order=station_code.asc";
msg.headers = {
    "apikey": key,
    "Authorization": "Bearer " + key,
    "Accept": "application/json"
};
msg._syncStep = "stations";
return msg;

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
    node.error("Không tải được stations. HTTP: " + msg.statusCode, msg);
    return null;
}

const map = {};
const meta = {};
const exact = { "ST001": "1", "ST002": "2", "ST003": "3" };

for (const row of msg.payload) {
    if (!row || !row.id || row.is_active === false) continue;
    const code = String(row.station_code || "").toUpperCase().trim();
    if (!code) continue;

    let num = exact[code] || null;
    if (!num) {
        if (/\bST0*1\b/.test(code)) num = "1";
        else if (/\bST0*2\b/.test(code)) num = "2";
        else if (/\bST0*3\b/.test(code)) num = "3";
    }
    if (!num) continue;

    map[num] = row.id;
    meta[num] = {
        stationNo: Number(num),
        stationId: row.id,
        stationCode: code.includes("ST001") ? "ST001" : code.includes("ST002") ? "ST002" : code.includes("ST003") ? "ST003" : code,
        isActive: row.is_active !== false,
        name: "Trạm sạc " + String(num).padStart(2, "0")
    };
}

global.set("evStationMap", map);
global.set("evStationMeta", meta);

const n = Object.keys(map).length;
node.status({
    fill: n === 3 ? "green" : (n > 0 ? "yellow" : "red"),
    shape: "dot",
    text: "Map " + n + "/3 trạm"
});

msg._syncStep = "tariffs";
msg.payload = { map: map, meta: meta, so_tram: n };
return msg;

const url = env.get("SUPABASE_URL");
const key = env.get("SUPABASE_SERVICE_ROLE_KEY");
if (!url || !key) {
    node.error("Thiếu env Supabase khi tải bảng giá", msg);
    return null;
}
const baseUrl = url.replace(/\/+$/, "").replace(/\/rest\/v1$/i, "");
msg.method = "GET";
msg.url = baseUrl + "/rest/v1/station_tariffs?select=*";
msg.headers = {
    "apikey": key,
    "Authorization": "Bearer " + key,
    "Accept": "application/json"
};
msg._syncStep = "tariffs";
return msg;

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
    node.error("Không tải được station_tariffs. HTTP " + msg.statusCode, msg);
    node.status({fill:"red", shape:"ring", text:"Tariff HTTP " + msg.statusCode});
    return null;
}

const map = global.get("evStationMap") || {};
const uuidToNo = {};
for (const [no, uuid] of Object.entries(map)) {
    uuidToNo[String(uuid)] = String(no);
}

const byStation = {};
let shared = null;

function pickRow(row) {
    return {
        currency: String(row.currency || "VND"),
        low: Math.max(0, Number(row.low_price ?? row.low ?? 0) || 0),
        normal: Math.max(0, Number(row.normal_price ?? row.normal ?? 0) || 0),
        peak: Math.max(0, Number(row.peak_price ?? row.peak ?? 0) || 0),
        lowStart: String(row.low_start || row.lowStart || "00:00"),
        lowEnd: String(row.low_end || row.lowEnd || "06:00"),
        peakStart: String(row.peak_start || row.peakStart || "17:30"),
        peakEnd: String(row.peak_end || row.peakEnd || "22:30"),
        updatedAt: row.updated_at || row.updatedAt || null,
        stationId: row.station_id || null
    };
}

for (const row of msg.payload) {
    if (!row) continue;
    const t = pickRow(row);
    const no = row.station_id ? uuidToNo[String(row.station_id)] : null;
    if (no) {
        byStation[no] = t;
    } else if (!shared) {
        shared = t;
    }
}

for (const no of ["1", "2", "3"]) {
    if (!byStation[no]) {
        byStation[no] = shared ? { ...shared, stationId: map[no] || null } : {
            currency: "VND", low: 0, normal: 0, peak: 0,
            lowStart: "00:00", lowEnd: "06:00",
            peakStart: "17:30", peakEnd: "22:30",
            updatedAt: null, stationId: map[no] || null
        };
    }
}

const primary = byStation["1"] || byStation["2"] || byStation["3"];
const tariffConfig = {
    currency: primary.currency,
    low: primary.low,
    normal: primary.normal,
    peak: primary.peak,
    lowStart: primary.lowStart,
    lowEnd: primary.lowEnd,
    peakStart: primary.peakStart,
    peakEnd: primary.peakEnd,
    version: "SUPABASE-" + (primary.updatedAt || Date.now()),
    updatedAt: primary.updatedAt || new Date().toISOString(),
    source: "supabase"
};

global.set("evTariff", byStation);
global.set("evTariffShared", tariffConfig);
flow.set("tariffConfig", tariffConfig);

node.status({
    fill: "green",
    shape: "dot",
    text: "Tariff " + Object.keys(byStation).length + " trạm • low=" + tariffConfig.low
});

msg.payload = {
    thanh_cong: true,
    so_tram_map: Object.keys(map).length,
    so_tariff: Object.keys(byStation).length,
    evStationMap: map,
    evTariff: byStation,
    tariffConfig: tariffConfig
};
return msg;

const t = (msg.payload && msg.payload.tariffConfig) || global.get("evTariffShared");
if (!t) return null;
msg.payload = { type: "tariff_update", tariff: t };
return msg;

const map = global.get("evStationMap") || {};
const uuids = Object.values(map).filter(Boolean);
if (!uuids.length) return null;

const baseUrl = String(env.get("SUPABASE_URL") || "").replace(/\/+$/, "").replace(/\/rest\/v1$/i, "");
const key = env.get("SUPABASE_SERVICE_ROLE_KEY");
if (!baseUrl || !key) return null;

const inList = uuids.map(u => '"' + u + '"').join(",");
msg.method = "GET";
msg.url = baseUrl + "/rest/v1/charging_sessions?status=eq.IN_PROGRESS&station_id=in.(" + inList + ")&select=*";
msg.headers = {
    "apikey": key,
    "Authorization": "Bearer " + key,
    "Accept": "application/json"
};
return msg;

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
    node.warn("Khôi phục phiên: HTTP " + msg.statusCode);
    return null;
}

const map = global.get("evStationMap") || {};
const uuidToNo = {};
for (const [no, uuid] of Object.entries(map)) uuidToNo[String(uuid)] = Number(no);

const sessions = {};
for (const row of msg.payload) {
    const no = uuidToNo[String(row.station_id)];
    if (!no) continue;
    sessions[no] = {
        stationId: no,
        sessionId: String(row.session_code || ""),
        startTime: row.started_at ? new Date(row.started_at).getTime() : Date.now(),
        lastTime: row.updated_at ? new Date(row.updated_at).getTime() : Date.now(),
        lastSequence: Number(row.last_sequence) || 0,
        lastTotalWh: Number(row.last_total_wh != null ? row.last_total_wh : row.energy_consumed_wh) || 0,
        energyWh: Number(row.energy_consumed_wh) || 0,
        energyByBand: {
            low: Number(row.energy_low_wh) || 0,
            normal: Number(row.energy_normal_wh) || 0,
            peak: Number(row.energy_peak_wh) || 0
        },
        costVnd: Number(row.total_cost) || 0,
        costByBand: {
            low: Number(row.cost_low) || 0,
            normal: Number(row.cost_normal) || 0,
            peak: Number(row.cost_peak) || 0
        },
        status: "CHARGING",
        tariffVersion: String(row.tariff_version || ""),
        tariffVersions: String(row.tariff_version || "").split(", ").filter(Boolean),
        lastPowerW: 0
    };
}

global.set("evSessionsRestore", sessions);
node.status({fill:"green", shape:"dot", text:"Khôi phục " + Object.keys(sessions).length + " phiên"});
msg.payload = { restored: Object.keys(sessions).length, sessions: sessions };
return msg;

const url = env.get("SUPABASE_URL");
const key = env.get("SUPABASE_SERVICE_ROLE_KEY");

if (!url || !key) {
    node.error("Thiếu SUPABASE_URL hoặc SUPABASE_SERVICE_ROLE_KEY", msg);
    return null;
}

const baseUrl = url.replace(/\/+$/, "").replace(/\/rest\/v1$/i, "");

msg.method = "GET";
msg.url = baseUrl + "/rest/v1/stations?select=id,station_code,is_active";
msg.headers = {
    "apikey": key,
    "Authorization": "Bearer " + key,
    "Accept": "application/json"
};

return msg;

msg.headers = msg.headers || {};
msg.headers["Access-Control-Allow-Origin"] = "*";
msg.headers["Access-Control-Allow-Methods"] = "GET,OPTIONS";
msg.headers["Access-Control-Allow-Headers"] = "Content-Type, Authorization";
msg.headers["Content-Type"] = "application/json; charset=utf-8";
if (String(msg.req && msg.req.method).toUpperCase() === "OPTIONS") {
    msg.statusCode = 204;
    msg.payload = "";
    return [null, msg];
}
return [msg, null];

const url = String(msg.req && (msg.req.url || msg.req.path) || "");

function stationPublic(no) {
    const meta = (global.get("evStationMeta") || {})[String(no)] || {};
    const live = (global.get("evStations") || {})[no] || {};
    const q = (global.get("evQueue") || {})[no] || {};
    const tariff = (global.get("evTariff") || {})[String(no)] || global.get("evTariffShared") || {};
    const conn = live.connectionStatus || "UNKNOWN";
    const op = live.status || "UNKNOWN";
    let display = "UNKNOWN";
    if (conn === "OFFLINE") display = "OFFLINE";
    else if (conn !== "ONLINE") display = "UNKNOWN";
    else if (op === "CHARGING") display = "CHARGING";
    else if (op === "FAULT") display = "FAULT";
    else if (op === "AVAILABLE") display = "AVAILABLE";
    return {
        id: Number(no),
        code: meta.stationCode || ("ST00" + no),
        name: meta.name || ("Trạm sạc " + String(no).padStart(2, "0")),
        status: display,
        connectionStatus: conn,
        operatingStatus: op,
        powerKw: Number(live.power) || 0,
        energyKwh: Number(live.energy) || 0,
        temperatureC: live.temperature,
        soc: live.soc,
        queueCount: q.queueCount ?? 0,
        estimatedWaitMinutes: q.estimatedWaitMinutes ?? 0,
        tariff: {
            currency: tariff.currency || "VND",
            low: tariff.low ?? 0,
            normal: tariff.normal ?? 0,
            peak: tariff.peak ?? 0,
            lowStart: tariff.lowStart || "00:00",
            lowEnd: tariff.lowEnd || "06:00",
            peakStart: tariff.peakStart || "17:30",
            peakEnd: tariff.peakEnd || "22:30"
        },
        updatedAt: live.lastSeen || null
    };
}

const parts = url.split("?")[0].split("/").filter(Boolean);
const idx = parts.indexOf("stations");
const stationId = idx >= 0 && parts[idx + 1] && /^\d+$/.test(parts[idx + 1]) ? Number(parts[idx + 1]) : null;
const sub = stationId && parts[idx + 2] ? parts[idx + 2] : null;

msg.headers = Object.assign({}, msg.headers, {
    "Access-Control-Allow-Origin": "*",
    "Content-Type": "application/json; charset=utf-8"
});

if (url.indexOf("/sessions/") >= 0) {
    const auth = (msg.req && msg.req.headers && (msg.req.headers.authorization || msg.req.headers.Authorization)) || "";
    if (!auth) {
        msg.statusCode = 401;
        msg.payload = { error: "Unauthorized", message: "Cần đăng nhập để xem phiên sạc cá nhân" };
        return msg;
    }
    msg.statusCode = 501;
    msg.payload = { error: "Not implemented", message: "Endpoint phiên cá nhân sẽ đọc charging_sessions theo user_id sau khi gắn auth" };
    return msg;
}

if (stationId && ![1,2,3].includes(stationId)) {
    msg.statusCode = 404;
    msg.payload = { error: "Not found", message: "Không có trạm " + stationId };
    return msg;
}

if (stationId && sub === "queue") {
    const q = (global.get("evQueue") || {})[stationId] || {};
    msg.statusCode = 200;
    msg.payload = {
        stationId,
        queueCount: q.queueCount ?? 0,
        estimatedWaitMinutes: q.estimatedWaitMinutes ?? 0,
        updatedAt: q.updatedAt || null
    };
    return msg;
}

if (stationId && sub === "tariff") {
    const tariff = (global.get("evTariff") || {})[String(stationId)] || global.get("evTariffShared") || {};
    msg.statusCode = 200;
    msg.payload = {
        stationId,
        currency: tariff.currency || "VND",
        low: tariff.low ?? 0,
        normal: tariff.normal ?? 0,
        peak: tariff.peak ?? 0,
        lowStart: tariff.lowStart || "00:00",
        lowEnd: tariff.lowEnd || "06:00",
        peakStart: tariff.peakStart || "17:30",
        peakEnd: tariff.peakEnd || "22:30",
        updatedAt: tariff.updatedAt || null
    };
    return msg;
}

if (stationId) {
    msg.statusCode = 200;
    msg.payload = stationPublic(stationId);
    return msg;
}

msg.statusCode = 200;
msg.payload = {
    stations: [1, 2, 3].map(stationPublic),
    serverTime: new Date().toISOString()
};
return msg;
